window.PROBLEM_SOURCES["swift-69"] = {"id": "swift-69", "language": "swift", "stub": {"path": "swift/practice_problems/problem_69_relay_coverage_planner.swift", "source": "// Problem 69: Relay Coverage Planner\n// Swift 6, macOS 14+ | Senior | approximately 45 minutes\n//\n// An operations team must cover a linear transport corridor with radio relays.\n// Each candidate has a position and radius. Find uncovered stretches, use the\n// fewest relays, report the selection, and preserve a handoff overlap.\n//\n// You choose the internal data structures; the public interface is the contract.\n// Store all mutable state in instance properties initialized by init. Never use\n// mutable global or static state. Immutable static constants are fine.\n/*\n# Example\nlet planner = RelayCoveragePlanner()\nlet corridor = 0...5\nlet relays = [Relay(id: \"r0\", position: 0, radius: 3),\n              Relay(id: \"r1\", position: 1, radius: 4)]\nplanner.reachRange(of: relays[1], corridor: corridor) // -> 0...5\ntry planner.gaps(coveredBy: relays, corridor: corridor) // -> []\ntry planner.minimumRelayCount(relays, corridor: corridor) // -> 1\ntry planner.minimumRelaySelection(relays, corridor: corridor) // -> [\"r1\"]\n*/\n// PART 1 - Reach ranges and gaps  (~10 min)\n// Clip each relay to the corridor and return every inclusive uncovered range.\n// Validate a positive-length corridor, radii, ids, and the supported count.\n//\n// PART 2 - How many relays  (~13 min)\n// Scan the coverage frontier, committing the relay that reaches furthest. A gap\n// is a typed failure carrying Part 1's exact ranges. Avoid a quadratic scan.\n//\n// PART 3 - Which relays  (~10 min)\n// Return the chosen ids in corridor order. Parts 2 and 3 must share one private\n// scanner so the count and reconstruction cannot disagree.\n//\n// PART 4 - Minimum handoff overlap  (~12 min)\n// Require adjacent selected ranges to overlap by at least the given margin.\n// Reuse the same scanner with the shifted eligibility frontier.\n\npublic struct Relay: Equatable, Sendable {\n    public let id: String; public let position: Int; public let radius: Int\n    public init(id: String, position: Int, radius: Int) { self.id = id; self.position = position; self.radius = radius }\n}\npublic enum CoverageError: Error, Equatable, Sendable {\n    case uncoverable(gaps: [ClosedRange<Int>]); case nonPositiveCorridorLength(Int)\n    case negativeRadius(id: String); case duplicateRelayID(String); case tooManyRelays(Int)\n    case negativeMargin(Int); case notImplemented\n}\npublic struct RelayCoveragePlanner: Sendable {\n    public static let maximumRelayCount = 100_000\n    public init() {}\n    public func reachRange(of relay: Relay, corridor: ClosedRange<Int>) -> ClosedRange<Int>? { nil }\n    public func gaps(coveredBy relays: [Relay], corridor: ClosedRange<Int>) throws(CoverageError) -> [ClosedRange<Int>] { throw .notImplemented }\n    public func minimumRelayCount(_ relays: [Relay], corridor: ClosedRange<Int>) throws(CoverageError) -> Int { throw .notImplemented }\n    public func minimumRelaySelection(_ relays: [Relay], corridor: ClosedRange<Int>) throws(CoverageError) -> [String] { throw .notImplemented }\n    public func minimumRelaySelection(_ relays: [Relay], corridor: ClosedRange<Int>, handoffMargin: Int) throws(CoverageError) -> [String] { throw .notImplemented }\n}\n"}, "test": {"path": "swift/Tests/Problem69RelayCoveragePlannerTests/Problem69RelayCoveragePlannerTests.swift", "source": "import Testing\n@testable import Problem69RelayCoveragePlanner\n\nprivate let corridor = 0...10\nprivate func relays() -> [Relay] { [Relay(id: \"left\", position: 1, radius: 3), Relay(id: \"middle\", position: 5, radius: 3), Relay(id: \"right\", position: 9, radius: 3)] }\n\n@Suite(\"Part 1 - Reach ranges and gaps\") struct RelayPart1Tests {\n    @Test func clipsAndFindsGaps() throws {\n        let planner = RelayCoveragePlanner()\n        #expect(planner.reachRange(of: Relay(id: \"clip\", position: 0, radius: 3), corridor: corridor) == 0...3)\n        #expect(try planner.gaps(coveredBy: [Relay(id: \"a-gap\", position: 0, radius: 1), Relay(id: \"b-gap\", position: 5, radius: 1)], corridor: 0...6) == [2...3])\n    }\n    @Test func validatesAndIsStateless() throws {\n        let first = RelayCoveragePlanner(), second = RelayCoveragePlanner(); _ = try first.gaps(coveredBy: relays(), corridor: corridor)\n        #expect(try second.gaps(coveredBy: relays(), corridor: corridor).isEmpty)\n        #expect(throws: CoverageError.negativeRadius(id: \"bad-radius\")) { try first.gaps(coveredBy: [Relay(id: \"bad-radius\", position: 0, radius: -1)], corridor: corridor) }\n    }\n}\n@Suite(\"Part 2 - How many relays\") struct RelayPart2Tests {\n    @Test func countsAndExplainsFailure() throws {\n        let planner = RelayCoveragePlanner(); #expect(try planner.minimumRelayCount(relays(), corridor: corridor) == 3)\n        #expect(throws: CoverageError.uncoverable(gaps: [2...8])) { try planner.minimumRelayCount([Relay(id: \"sparse-left\", position: 0, radius: 1), Relay(id: \"sparse-right\", position: 10, radius: 1)], corridor: corridor) }\n    }\n}\n@Suite(\"Part 3 - Which relays\") struct RelayPart3Tests {\n    @Test func reconstructsSameGreedy() throws {\n        let planner = RelayCoveragePlanner(), input = relays(); let selected = try planner.minimumRelaySelection(input, corridor: corridor)\n        #expect(selected == [\"left\", \"middle\", \"right\"]); #expect(selected.count == (try planner.minimumRelayCount(input, corridor: corridor)))\n        let selectedRelays = input.filter { selected.contains($0.id) }; #expect(try planner.gaps(coveredBy: selectedRelays, corridor: corridor).isEmpty)\n    }\n}\n@Suite(\"Part 4 - Minimum handoff overlap\") struct RelayPart4Tests {\n    @Test func enforcesMargin() throws {\n        let planner = RelayCoveragePlanner(); let input = [Relay(id: \"wide-left\", position: 2, radius: 4), Relay(id: \"wide-right\", position: 8, radius: 4)]\n        #expect(try planner.minimumRelaySelection(input, corridor: corridor, handoffMargin: 2) == [\"wide-left\", \"wide-right\"])\n        #expect(throws: CoverageError.negativeMargin(-1)) { try planner.minimumRelaySelection(input, corridor: corridor, handoffMargin: -1) }\n    }\n}\n"}, "parts": [{"part": 1, "source": "// PART 1 - Reach ranges and gaps  (~10 min)\n// Clip each relay to the corridor and return every inclusive uncovered range.\n// Validate a positive-length corridor, radii, ids, and the supported count.\n//\n//\n"}, {"part": 2, "source": "// PART 2 - How many relays  (~13 min)\n// Scan the coverage frontier, committing the relay that reaches furthest. A gap\n// is a typed failure carrying Part 1's exact ranges. Avoid a quadratic scan.\n//\n//\n"}, {"part": 3, "source": "// PART 3 - Which relays  (~10 min)\n// Return the chosen ids in corridor order. Parts 2 and 3 must share one private\n// scanner so the count and reconstruction cannot disagree.\n//\n//\n"}, {"part": 4, "source": "// PART 4 - Minimum handoff overlap  (~12 min)\n// Require adjacent selected ranges to overlap by at least the given margin.\n// Reuse the same scanner with the shifted eligibility frontier.\n\npublic struct Relay: Equatable, Sendable {\n    public let id: String; public let position: Int; public let radius: Int\n    public init(id: String, position: Int, radius: Int) { self.id = id; self.position = position; self.radius = radius }\n}\npublic enum CoverageError: Error, Equatable, Sendable {\n    case uncoverable(gaps: [ClosedRange<Int>]); case nonPositiveCorridorLength(Int)\n    case negativeRadius(id: String); case duplicateRelayID(String); case tooManyRelays(Int)\n    case negativeMargin(Int); case notImplemented\n}\npublic struct RelayCoveragePlanner: Sendable {\n    public static let maximumRelayCount = 100_000\n    public init() {}\n    public func reachRange(of relay: Relay, corridor: ClosedRange<Int>) -> ClosedRange<Int>? { nil }\n    public func gaps(coveredBy relays: [Relay], corridor: ClosedRange<Int>) throws(CoverageError) -> [ClosedRange<Int>] { throw .notImplemented }\n    public func minimumRelayCount(_ relays: [Relay], corridor: ClosedRange<Int>) throws(CoverageError) -> Int { throw .notImplemented }\n    public func minimumRelaySelection(_ relays: [Relay], corridor: ClosedRange<Int>) throws(CoverageError) -> [String] { throw .notImplemented }\n    public func minimumRelaySelection(_ relays: [Relay], corridor: ClosedRange<Int>, handoffMargin: Int) throws(CoverageError) -> [String] { throw .notImplemented }\n}\n"}], "implementationSurface": "public struct Relay: Equatable, Sendable {\n    public let id: String; public let position: Int; public let radius: Int\n    public init(id: String, position: Int, radius: Int) { self.id = id; self.position = position; self.radius = radius }\n}\npublic enum CoverageError: Error, Equatable, Sendable {\n    case uncoverable(gaps: [ClosedRange<Int>]); case nonPositiveCorridorLength(Int)\n    case negativeRadius(id: String); case duplicateRelayID(String); case tooManyRelays(Int)\n    case negativeMargin(Int); case notImplemented\n}\npublic struct RelayCoveragePlanner: Sendable {\n    public static let maximumRelayCount = 100_000\n    public init() {}\n    public func reachRange(of relay: Relay, corridor: ClosedRange<Int>) -> ClosedRange<Int>? { nil }\n    public func gaps(coveredBy relays: [Relay], corridor: ClosedRange<Int>) throws(CoverageError) -> [ClosedRange<Int>] { throw .notImplemented }\n    public func minimumRelayCount(_ relays: [Relay], corridor: ClosedRange<Int>) throws(CoverageError) -> Int { throw .notImplemented }\n    public func minimumRelaySelection(_ relays: [Relay], corridor: ClosedRange<Int>) throws(CoverageError) -> [String] { throw .notImplemented }\n    public func minimumRelaySelection(_ relays: [Relay], corridor: ClosedRange<Int>, handoffMargin: Int) throws(CoverageError) -> [String] { throw .notImplemented }\n}\n"};
